[
  {
    "id": "no_carts_between_facing_shelves",
    "text": "A shopper must not take a cart into an aisle segment where shelves face the shopper from both sides.",
    "abstraction": {
      "state_properties": {
        "facing_shelves": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS"
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "facing_shelves"
        ]
      }
    },
    "justification": "The rule is defined by the relative arrangement of shelves around the shopper, not by any particular cell or coordinate."
  },
  {
    "id": "enter_single_file_shelf_aisle_on_foot",
    "text": "A shopper may enter a single-file shelf aisle only while not holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "facing_shelves": {
          "or": [
            {
              "and": [
