              "and": [
                "shelfN",
                "shelfS"
              ]
            }
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "facing_shelves",
            {
              "or": [
                {
                  "le": [
                    "freeWidthH",
                    2
                  ]
                },
                {
                  "le": [
                    "freeWidthV",
                    2
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "enter_single_file_shelf_aisle": {
          "pre": {
            "and": [
              {
                "or": [
                  "MOVE",
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              },
              {
                "not": "single_file_shelf_aisle"
              }
            ]
          },
          "post": "single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "enter_single_file_shelf_aisle",
          "hasCart"
        ]
      }
    },
    "justification": "The norm refers to entering any narrow aisle with shelves on both sides, a layout-independent shopping-space relation."
  },
  {
